import re, json, os

d = os.environ.get('RLM_SESSION_DIR')
t_path = os.path.join(d, '../../sessions/' + os.path.basename(d) + '.jsonl')
t = open(t_path).read().replace('\\n', '\n')

G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows_data = t[m.end():].split('\n')[:h]
    rows = [r.split() for r in rows_data]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

test_input = G['Test input']

# Analyze the test input for "interesting" patterns
print("Test Input Analysis:")
for i, row in enumerate(test_input):
    unique = set(row)
    print(f"Row {i}: {row} (unique values: {sorted(unique)})")

# Look for "special" values (not background, not uniform rows)
# In demo cases:
# - Demo 1: background seems to be 0, divider is 6
# - Demo 2: background seems to be 7, divider is 9

# What defines "background"? The most common value?
def analyze_grid(grid):
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    return sorted(counts.items(), key=lambda x: -x[1])

counts = analyze_grid(test_input)
print(f"\nValue frequency: {counts}")

# Check if we can find regions
rows, cols = len(test_input), len(test_input[0])
print(f"\nDimensions: {rows}x{cols}")

# Try various transformations
def identity(grid):
    return [row[:] for row in grid]

def hflip(grid):
    return [row[::-1] for row in grid]

def vflip(grid):
    return grid[::-1]

def rot90(grid):
    # Rotate 90 degrees clockwise
    return [list(col)[::-1] for col in zip(*grid)]

def rot270(grid):
    return [list(col) for col in zip(*grid)][::-1]

def rot180(grid):
    return [row[::-1] for row in grid[::-1]]

results = {
    'identity': identity(test_input),
    'hflip': hflip(test_input),
    'vflip': vflip(test_input),
    'rot90': rot90(test_input),
    'rot180': rot180(test_input),
}

for name, result in results.items():
    print(f"\n{name}: {json.dumps(result)}")

